using HomestayBooking.Desktop.Models;
using System.Text.Json;
using static System.Windows.Forms.LinkLabel;
namespace HomestayBooking.Desktop.View;
public partial class FrmCreateBooking : Form
{
    private Guid _currentSubmissionId = Guid.NewGuid();
    public FrmCreateBooking() { InitializeComponent();


        cboChannel.SelectedItem="Phone";dtpCheckIn.Value=DateTime.Today.AddDays(1); dtpCheckOut.Value=dtpCheckIn.Value.AddDays(1); txtPhone.TextChanged+=(_,_)=>RenewSubmission();txtFullName.TextChanged+=(_,_)=>RenewSubmission();txtEmail.TextChanged+=(_,_)=>RenewSubmission();txtSpecialRequests.TextChanged+=(_,_)=>RenewSubmission();dtpCheckIn.ValueChanged+=(_,_)=>RenewSubmission();dtpCheckOut.ValueChanged+=(_,_)=>RenewSubmission();cboRoomType.SelectedValueChanged+=(_,_)=>RenewSubmission();btnCheckAvailability.Click += async (_,_) => await LoadAvailabilityAsync();btnPrevPage.Click+=async(_,_)=>{if(_page>1){_page--;await LoadAvailabilityAsync();}};btnNextPage.Click+=async(_,_)=>{_page++;await LoadAvailabilityAsync();}; btnSubmitBooking.Click += async (_,_) => await SubmitAsync(); btnResetForm.Click += (_,_) => ResetForm(); cboHomestay.SelectedIndexChanged += async (_,_) => await LoadRoomTypesAsync(); Load += async (_,_) => await LoadOptionsAsync(); dgvAvailability.CellDoubleClick += async (_,_) => await SelectAvailableRoomAsync(); }
    private void RenewSubmission()=>_currentSubmissionId=Guid.NewGuid();
    private static System.Data.DataTable Rows(JsonElement data) => DesktopApi.ToTable(data.TryGetProperty("items",out var items) && items.ValueKind==JsonValueKind.Array ? items.EnumerateArray() : []);
    private async Task LoadOptionsAsync(){try{var areas=await DesktopApi.GetAllAsync<JsonElement>("areas");cboArea.DisplayMember="name";cboArea.ValueMember="id";cboArea.DataSource=new[]{new{id=(int?)null,name="Tất cả khu vực"}}.Concat(areas.Select(a=>new{id=(int?)a.GetProperty("id").GetInt32(),name=a.GetProperty("name").GetString()!})).ToList();var homes=await DesktopApi.GetAllAsync<JsonElement>("booking-homestays");cboHomestay.DisplayMember="name";cboHomestay.ValueMember="id";cboHomestay.DataSource=homes.Select(h=>new{id=h.GetProperty("id").GetInt32(),name=h.GetProperty("name").GetString()!}).ToList();}catch(Exception ex){DesktopApi.ShowError(this,ex);}}
    private async Task LoadRoomTypesAsync(){try{if(cboHomestay.SelectedValue is not int id)return;var types=await DesktopApi.GetAsync<JsonElement>($"booking-homestays/{id}/room-types");cboRoomType.DisplayMember="name";cboRoomType.ValueMember="id";cboRoomType.DataSource=types.EnumerateArray().Select(t=>new{id=t.GetProperty("id").GetInt32(),name=$"{t.GetProperty("name").GetString()} · tối đa {t.GetProperty("maxGuests").GetInt32()} khách"}).ToList();}catch(Exception ex){DesktopApi.ShowError(this,ex);}}
    private async Task LoadAvailabilityAsync() { try { var area=cboArea.SelectedValue is int id?$"&areaId={id}":""; var data=await DesktopApi.GetAsync<JsonElement>($"availability?checkIn={dtpCheckIn.Value:yyyy-MM-dd}&checkOut={dtpCheckOut.Value:yyyy-MM-dd}{area}&guests={numGuests.Value}&page={_page}");dgvAvailability.DataSource=Rows(data);DesktopApi.ShowColumns(dgvAvailability,("homestayName","Homestay"),("areaName","Khu vực"),("roomTypeName","Loại phòng"),("maxGuests","Tối đa khách"),("freeRooms","Còn trống"),("totalPrice","Tổng giá"),("rating","Đánh giá"));lblPageInfo.Text=$"Trang {data.GetProperty("page").GetInt32()} / {data.GetProperty("totalPages").GetInt32()} · {data.GetProperty("totalCount").GetInt32()} loại phòng";} catch(Exception ex){DesktopApi.ShowError(this,ex);} }
    private async Task SelectAvailableRoomAsync(){if(dgvAvailability.CurrentRow is null)return;cboHomestay.SelectedValue=ReadInt(dgvAvailability.CurrentRow.Cells["homestayId"].Value);await LoadRoomTypesAsync();cboRoomType.SelectedValue=ReadInt(dgvAvailability.CurrentRow.Cells["roomTypeId"].Value);}
    private static int ReadInt(object? value)=>value is JsonElement e?e.GetInt32():Convert.ToInt32(value);
    private int _page=1;
    private async Task SubmitAsync() { try { btnSubmitBooking.Enabled=false; var result=await DesktopApi.PostAsync<JsonElement>("bookings",new {phone=txtPhone.Text,fullName=txtFullName.Text,email=string.IsNullOrWhiteSpace(txtEmail.Text)?null:txtEmail.Text,roomTypeId=cboRoomType.SelectedValue,checkIn=dtpCheckIn.Value.ToString("yyyy-MM-dd"),checkOut=dtpCheckOut.Value.ToString("yyyy-MM-dd"),guests=(int)numGuests.Value,specialRequests=txtSpecialRequests.Text,channel=cboChannel.Text,submissionId=_currentSubmissionId}); if(result.ValueKind==JsonValueKind.Object){var details=await DesktopApi.GetAsync<JsonElement>($"bookings/{result.GetProperty("id").GetInt32()}");var booking=details.GetProperty("booking");lblResult.Text=$"Mã đơn: {booking.GetProperty("code").GetString()} · Trạng thái: {booking.GetProperty("status").GetString()} · Hạn giữ: {booking.GetProperty("holdExpiresAt").GetDateTime().ToLocalTime():dd/MM HH:mm} · Tiền cọc: {booking.GetProperty("amountDue").GetDecimal():N0} đ";} _currentSubmissionId=Guid.NewGuid(); } catch(Exception ex){DesktopApi.ShowError(this,ex);} finally{btnSubmitBooking.Enabled=true;} }
    private void ResetForm(){txtPhone.Clear();txtFullName.Clear();txtEmail.Clear();txtSpecialRequests.Clear();lblResult.Text="";_currentSubmissionId=Guid.NewGuid();}
}
